#!/usr/bin/env python3
"""Bounded public research captures, with exact source metadata and compressed bytes."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'wlrn-results': 'https://www.wlrn.org/state-level-results', 'wlrn-2026': 'https://www.wlrn.org/tags/2026-elections', 'dos-home': 'https://dos.fl.gov/elections/', 'dos-electionwatch': 'https://floridaelectionwatch.gov/Home/ES/', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'wusf-vote2026': 'https://www.wusf.org/vote2026', 'wesh-politics': 'https://www.wesh.com/politics', 'news4jax-primary': 'https://www.news4jax.com/vote-2026/2026/08/18/vote-2026-election-results-in-state-local-races-for-the-aug-18-2026-florida-primary/', 'wjhg-results': 'https://www.wjhg.com/politics/election-results/', 'wusf-primary-results': 'https://www.wusf.org/politics-issues/2026-08-18/2026-florida-primary-elections-results-governor-house-state-senate-statewide-offices', 'wusf-freshtake-embed': 'https://www.freshtake.vote/enr/embed.php?county=HIL&race=58053', 'dos-precinct-data-index': 'https://dos.fl.gov/elections/data-statistics/elections-data/precinct-level-election-results/', 'dos-2024-senate-county': 'https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11%2F5%2F2024&GRP=&PARTY=&RACE=USS', 'dos-2024-races-index': 'https://results.elections.myflorida.com/ElectionRaces.asp?ElectionDate=11%2F5%2F2024', 'dos-2022-federal-summary': 'https://results.elections.myflorida.com/SummaryRpt.asp?DATAMODE=&ElectionDate=11%2F8%2F2022&Race=FED', 'dos-2024-precinct-zip': 'https://dos.fl.gov/media/708761/2024-gen-outputofficial1.zip', 'dos-2022-precinct-zip': 'https://dos.fl.gov/media/706300/2022-gen-outputofficial.zip', 'dos-2020-precinct-zip': 'https://fldoswebumbracoprod.blob.core.windows.net/media/703763/2020-general-election-rev.zip', 'dos-precinct-schema': 'https://dos.fl.gov/media/709209/final-precinct-level-elections-data-definitions-and-field-codes_20250624.pdf', 'dos-2024-precinct-official-storage-alias': 'https://fldoswebumbracoprod.blob.core.windows.net/media/708761/2024-gen-outputofficial1.zip', 'dos-2022-precinct-official-storage-alias': 'https://fldoswebumbracoprod.blob.core.windows.net/media/706300/2022-gen-outputofficial.zip', 'dos-precinct-schema-official-storage-alias': 'https://fldoswebumbracoprod.blob.core.windows.net/media/709209/final-precinct-level-elections-data-definitions-and-field-codes_20250624.pdf', 'archive-cdx-2024-senate-detail': 'https://web.archive.org/cdx/search/cdx?url=results.elections.myflorida.com%2FDetailRpt.Asp%2A&output=json&filter=statuscode%3A200&filter=original%3A.%2A2024.%2A&filter=original%3A.%2A%5BRr%5D%5BAa%5D%5BCc%5D%5BEe%5D%3D%5BUu%5D%5BSs%5D%5BSs%5D.%2A&collapse=urlkey', 'archive-cdx-2022-senate-detail': 'https://web.archive.org/cdx/search/cdx?url=results.elections.myflorida.com%2FDetailRpt.Asp%2A&output=json&filter=statuscode%3A200&filter=original%3A.%2A2022.%2A&filter=original%3A.%2A%5BRr%5D%5BAa%5D%5BCc%5D%5BEe%5D%3D%5BUu%5D%5BSs%5D%5BSs%5D.%2A&collapse=urlkey', 'electionwatch-downloads': 'https://floridaelectionwatch.gov/Downloads', 'dos-2024-senate-canonical-order': 'https://results.elections.myflorida.com/DetailRpt.Asp?ELECTIONDATE=11/5/2024&RACE=USS&DIST=&GRP=&DATAMODE=&PARTY=', 'nara-2024-index': 'https://www.archives.gov/electoral-college/2024', 'nara-2024-ascertainment': 'https://www.archives.gov/files/electoral-college/2024/ascertainment-florida.pdf', 'wptv-results-current': 'https://www.wptv.com/election-results', 'wtxl-results-current': 'https://www.wtxl.com/election-results', 'wesh-august-primary': 'https://www.wesh.com/article/results-florida-primary-election-governor-race-us-senate/73427623', 'wgcu-august-counting': 'https://news.wgcu.org/text/top-story/2026-08-18/primary-election-in-person-voting-gets-under-way-amid-continuing-heat-advisory', 'wptv-published-xml': 'https://mediaassets.wptv.com/NWT/electionresults/elections.xml', 'wtxl-published-xml': 'https://mediaassets.wtxl.com/NWT/electionresults/elections.xml', 'wtxl-magis-observed': 'https://digital.magis.media/magisMapping/index.php?station=wtxldigital008028', 'wesh-august-ap-panel': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/58670/32107.html', 'wesh-august-local-embed': 'https://ehub.htvapps.com/wesh/wp-json/election-hub/v1/iframe-embed/1469', 'wesh-august-local-widget': 'https://ehub.htvapps.com/wesh/wp-json/election-hub/v1/widget/1469', 'dos-2024-senate-fresh-original': 'https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11%2F5%2F2024&GRP=&PARTY=&RACE=USS', 'archive-cdx-all-detail-prefix': 'https://web.archive.org/cdx/search/cdx?url=results.elections.myflorida.com%2FDetailRpt.Asp%2A&output=json&filter=statuscode%3A200&collapse=urlkey&fl=timestamp%2Coriginal%2Cstatuscode%2Cdigest&filter=original%3A.%2A2024.%2A', 'dos-2024-president-archive-20261009173646': 'https://web.archive.org/web/20261009173646id_/https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11%2F5%2F2024&GRP=&PARTY=&RACE=PRE', 'archive-cdx-2022-all-detail-prefix': 'https://web.archive.org/cdx/search/cdx?url=results.elections.myflorida.com%2FDetailRpt.Asp%2A&output=json&filter=statuscode%3A200&collapse=urlkey&fl=timestamp%2Coriginal%2Cstatuscode%2Cdigest&filter=original%3A.%2A2022.%2A', 'duval-cdx-1141': 'https://web.archive.org/cdx/search/cdx?url=www.duvalelections.gov%2FDocumentCenter%2FView%2F1141%2F%2A&output=json&filter=statuscode%3A200&collapse=digest&limit=500&fl=timestamp%2Coriginal%2Cmimetype%2Cstatuscode%2Cdigest%2Clength', 'duval-cdx-1542': 'https://web.archive.org/cdx/search/cdx?url=www.duvalelections.gov%2FDocumentCenter%2FView%2F1542%2F%2A&output=json&filter=statuscode%3A200&collapse=digest&limit=500&fl=timestamp%2Coriginal%2Cmimetype%2Cstatuscode%2Cdigest%2Clength', 'duval-cdx-legacy-pdf': 'https://web.archive.org/cdx/search/cdx?url=www.duvalelections.com%2F%2Aprecinct%2A.pdf&output=json&filter=statuscode%3A200&collapse=digest&limit=500&fl=timestamp%2Coriginal%2Cmimetype%2Cstatuscode%2Cdigest%2Clength', 'duval-archived-countywide-pdf': 'https://web.archive.org/web/20260106081626id_/https://www.duvalelections.gov/DocumentCenter/View/1141/School-Board-County-Wide-PDF'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
